import { createFakeFirestore } from './__test-helpers__/fake-firestore';
import {
  GENESIS_SETTLEMENT_POLICY_EVENT_COLLECTION,
  INITIAL_GENESIS_SETTLEMENT_CAP_ATOMIC,
  createGenesisSettlementBudgetPolicyEvent,
  loadAuthorizedGenesisSettlementPolicyEvent,
} from './genesis-settlement-budget';
import {
  decodeOpenSshEd25519PublicKey,
  type SshApprovalSignature,
} from './policy/approval-signature';
import {
  PVT_APPROVAL_MANIFEST_BYTES_COLLECTION,
  approvalManifestSha256,
} from './policy/current-approval';
import { PROPOSED_GENESIS_CAMPAIGN_POLICY } from './policy/proposed-genesis-policy';
import { GENESIS_SETTLEMENT_APPROVAL_MANIFEST_SHA256 } from './policy/genesis-settlement-approval-manifest';
import {
  GENESIS_SETTLEMENT_AUTHORIZATION_SCOPE,
  GENESIS_SETTLEMENT_CAMPAIGN_ID,
  GENESIS_SETTLEMENT_CHAIN_ID,
  GENESIS_SETTLEMENT_KERNEL_ID,
} from './policy/genesis-settlement-authorization';

const fixtureDir = path.join(__dirname, 'policy', '__fixtures__', 'approval');
const publicKey = fs.readFileSync(path.join(fixtureDir, 'fixture-key.pub'), 'utf8').trim();
const publicKeyHash = decodeOpenSshEd25519PublicKey(publicKey).sha256;
const bytes = (name: 'a' | 'b') => fs.readFileSync(path.join(fixtureDir, `manifest-${name}.json`));
const signature = (name: 'a' | 'b'): SshApprovalSignature => ({
  scheme: 'sshsig-ed25519',
  signer_identity: 'frank',
  namespace: 'provian-pvt-policy',
  public_key_sha256: publicKeyHash,
  armored_signature: fs.readFileSync(path.join(fixtureDir, `manifest-${name}.json.sig`), 'utf8'),
});

function initialEvent() {
  return createGenesisSettlementBudgetPolicyEvent({
    event_id: 'fixture-initial',
    policy_version: PROPOSED_GENESIS_CAMPAIGN_POLICY.policy_version,
    authorized_at_epoch: 0,
    effective_epoch: 0,
    cap_atomic: INITIAL_GENESIS_SETTLEMENT_CAP_ATOMIC,
    approval_status: 'approved_by_frank',
    approval_manifest_sha256: GENESIS_SETTLEMENT_APPROVAL_MANIFEST_SHA256,
    approval_signature: signature('a'),
    approval_audit_id: 'fixture-audit-a',
    authorization_scope: GENESIS_SETTLEMENT_AUTHORIZATION_SCOPE,
    chain_id: GENESIS_SETTLEMENT_CHAIN_ID,
    campaign_id: GENESIS_SETTLEMENT_CAMPAIGN_ID,
    settlement_kernel_id: GENESIS_SETTLEMENT_KERNEL_ID,
    automation_generated: false,
    previous_event_hash: null,
    evented_at_ms: 1,
    evented_by: 'fixture',
  });
}

function laterEvent(
  previousEventHash: string,
  manifestHash: string,
  approvalSignature: SshApprovalSignature,
  overrides: Partial<Pick<
  ReturnType<typeof initialEvent>,
  | 'event_id'
  | 'policy_version'
  | 'authorized_at_epoch'
  | 'effective_epoch'
  | 'cap_atomic'
  | 'previous_event_hash'
  >> = {},
) {
  return createGenesisSettlementBudgetPolicyEvent({
    event_id: 'fixture-later',
    policy_version: 'fixture-policy-b',
    authorized_at_epoch: 1,
    effective_epoch: 2,
    cap_atomic: (8_000_000n * 10n ** 18n).toString(),
    approval_status: 'approved_by_frank',
    approval_manifest_sha256: manifestHash,
    approval_signature: approvalSignature,
    approval_audit_id: 'fixture-audit-b',
    authorization_scope: GENESIS_SETTLEMENT_AUTHORIZATION_SCOPE,
    chain_id: GENESIS_SETTLEMENT_CHAIN_ID,
    campaign_id: GENESIS_SETTLEMENT_CAMPAIGN_ID,
    settlement_kernel_id: GENESIS_SETTLEMENT_KERNEL_ID,
    automation_generated: false,
    previous_event_hash: previousEventHash,
    evented_at_ms: 2,
    evented_by: 'fixture',
    ...overrides,
  });
}

async function installManifestB(fake: ReturnType<typeof createFakeFirestore>): Promise<string> {
  const manifestB = bytes('b');
  const hashB = approvalManifestSha256(manifestB);
  await fake.collection(PVT_APPROVAL_MANIFEST_BYTES_COLLECTION)
    .doc(hashB.slice('sha256:'.length))
    .set({
      schema_version: 'pvt-approval-manifest-bytes/v1',
      approval_manifest_sha256: hashB,
      manifest_utf8_base64: manifestB.toString('base64'),
      registered_at_ms: 1,
      registered_by: 'fixture',
    });
  return hashB;
}

async function putEvents(
  fake: ReturnType<typeof createFakeFirestore>,
  laterHash: string,
  laterSignature: SshApprovalSignature,
  overrides: Parameters<typeof laterEvent>[3] = {},
): Promise<void> {
  const first = initialEvent();
  const second = laterEvent(first.event_hash, laterHash, laterSignature, overrides);
  await fake.collection(GENESIS_SETTLEMENT_POLICY_EVENT_COLLECTION)
    .doc(first.event_id).set(first as unknown as Record<string, unknown>);
  await fake.collection(GENESIS_SETTLEMENT_POLICY_EVENT_COLLECTION)
    .doc(second.event_id).set(second as unknown as Record<string, unknown>);
}

describe('Genesis settlement event exact-manifest approval binding', () => {
  const oldPublicKey = process.env.FRANK_PVT_APPROVAL_SSH_PUBLIC_KEY;
  const oldKeyHash = process.env.FRANK_PVT_APPROVAL_SSH_KEY_SHA256;

  beforeAll(() => {
    process.env.FRANK_PVT_APPROVAL_SSH_PUBLIC_KEY = publicKey;
    process.env.FRANK_PVT_APPROVAL_SSH_KEY_SHA256 = publicKeyHash;
  });
  afterAll(() => {
    if (oldPublicKey === undefined) delete process.env.FRANK_PVT_APPROVAL_SSH_PUBLIC_KEY;
    else process.env.FRANK_PVT_APPROVAL_SSH_PUBLIC_KEY = oldPublicKey;
    if (oldKeyHash === undefined) delete process.env.FRANK_PVT_APPROVAL_SSH_KEY_SHA256;
    else process.env.FRANK_PVT_APPROVAL_SSH_KEY_SHA256 = oldKeyHash;
  });

  it('verifies historical A and a genuine later B independently', async () => {
    const fake = createFakeFirestore();
    const hashB = await installManifestB(fake);
    await putEvents(fake, hashB, signature('b'));
    const db = fake as unknown as Firestore;
    await expect(loadAuthorizedGenesisSettlementPolicyEvent(db, 0))
      .resolves.toMatchObject({ event_id: 'fixture-initial' });
    await expect(loadAuthorizedGenesisSettlementPolicyEvent(db, 2))
      .resolves.toMatchObject({
        event_id: 'fixture-later',
        approval_manifest_sha256: hashB,
        cap_atomic: (8_000_000n * 10n ** 18n).toString(),
      });
  });

  it.each([
    ['cap', { cap_atomic: (9_000_000n * 10n ** 18n).toString() }, 2],
    ['policy version', { policy_version: 'fixture-policy-b-mutated' }, 2],
    ['authorized epoch', { authorized_at_epoch: 0 }, 2],
    ['effective epoch', { effective_epoch: 3 }, 3],
    ['previous-event hash', { previous_event_hash: `sha256:${'c'.repeat(64)}` }, 2],
    ['event id', { event_id: 'fixture-later-mutated' }, 2],
  ] as const)(
    'does not let genuine B authorize a changed %s',
    async (_label, overrides, effectiveEpoch) => {
      const fake = createFakeFirestore();
      const hashB = await installManifestB(fake);
      await putEvents(fake, hashB, signature('b'), overrides);
      await expect(loadAuthorizedGenesisSettlementPolicyEvent(
        fake as unknown as Firestore,
        effectiveEpoch,
      )).rejects.toThrow('signed authorization does not match policy event');
    },
  );

  it('does not let genuine B authorize a changed scope', async () => {
    const fake = createFakeFirestore();
    const hashB = await installManifestB(fake);
    const first = initialEvent();
    const second = laterEvent(first.event_hash, hashB, signature('b'));
    await fake.collection(GENESIS_SETTLEMENT_POLICY_EVENT_COLLECTION)
      .doc(first.event_id).set(first as unknown as Record<string, unknown>);
    await fake.collection(GENESIS_SETTLEMENT_POLICY_EVENT_COLLECTION)
      .doc(second.event_id).set({
        ...second,
        authorization_scope: 'combined_system_budget',
      });
    await expect(loadAuthorizedGenesisSettlementPolicyEvent(
      fake as unknown as Firestore,
      2,
    )).rejects.toThrow('invalid Genesis settlement policy event document');
  });

  it('does not let signature A authorize an event declaring manifest B', async () => {
    const fake = createFakeFirestore();
    const hashB = await installManifestB(fake);
    await putEvents(fake, hashB, signature('a'));
    const db = fake as unknown as Firestore;
    // A future invalid event does not retroactively invalidate the historical A event.
    await expect(loadAuthorizedGenesisSettlementPolicyEvent(db, 0))
      .resolves.toMatchObject({ event_id: 'fixture-initial' });
    await expect(loadAuthorizedGenesisSettlementPolicyEvent(db, 2))
      .rejects.toThrow('approval signature is invalid');
  });

  it('rejects an unknown manifest hash when that event becomes effective', async () => {
    const fake = createFakeFirestore();
    await putEvents(fake, `sha256:${'f'.repeat(64)}`, signature('b'));
    await expect(loadAuthorizedGenesisSettlementPolicyEvent(
      fake as unknown as Firestore,
      2,
    )).rejects.toThrow('approval signature is invalid');
  });
});
